class Ledger
  def initialize(entries = [])
    @entries = entries.dup
  end

  def add(entry)
    @entries << entry
    self
  end

  def entries
    @entries
  end

  def freeze
    @entries.freeze
    super
  end

  def initialize_dup(other)
    @entries = other.entries.dup
    super
  end

  def initialize_clone(other, freeze: nil)
    @entries = other.entries.dup

    should_freeze =
      if freeze.nil?
        other.frozen?
      else
        freeze
      end

    @entries.freeze if should_freeze

    super(other, freeze: freeze)
  end
end
